@namespace sv_26532cc249fe4d319344f13ca541e7ff.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxLength" @bind="CoverLetter" @bind:event="oninput"></textarea>
        <span class="char-count">@CoverLetter.Length / @MaxLength characters</span>
    </div>

    <div class="step-actions">
        <button class="btn-back" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_26532cc249fe4d319344f13ca541e7ff.Components.Pages.Apply

<div class="step-content">
    <h2>Review & Submit</h2>

    <section class="review-section">
        <h3>Personal Information <button class="btn-edit" @onclick='() => OnEditSection.InvokeAsync(0)'>Edit</button></h3>
        <dl>
            <dt>Name</dt><dd>@FullName</dd>
            <dt>Email</dt><dd>@Email</dd>
            <dt>Phone</dt><dd>@Phone</dd>
            <dt>Address</dt><dd>@Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <h3>Work History <button class="btn-edit" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</button></h3>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-item">
                <strong>@entry.Title</strong> at @entry.Company<br />
                <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <h3>References <button class="btn-edit" @onclick='() => OnEditSection.InvokeAsync(2)'>Edit</button></h3>
        @foreach (var r in References)
        {
            <div class="review-item">
                <strong>@r.Name</strong> (@r.Relationship)<br />
                @r.Email &bull; @r.Phone
            </div>
        }
    </section>

    <section class="review-section">
        <h3>Cover Letter <button class="btn-edit" @onclick='() => OnEditSection.InvokeAsync(3)'>Edit</button></h3>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    <div class="step-actions">
        <button class="btn-back" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-submit" @onclick="() => OnSubmit.InvokeAsync()" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = [];
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
