@page "/apply"
@using sv_26532cc249fe4d319344f13ca541e7ff.Components.Pages.Apply
@using sv_26532cc249fe4d319344f13ca541e7ff.Models
@using sv_26532cc249fe4d319344f13ca541e7ff.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" StepNames="stepNames" OnStepClicked="GoToStep" />

    @if (submittedId.HasValue)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your confirmation number is:</p>
            <p class="application-id">@submittedId.Value</p>
        </div>
    }
    else
    {
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep References="references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                            WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting"
                            OnEditSection="GoToStep" OnBack="GoBack" OnSubmit="HandleSubmit" />
                break;
        }
    }
</div>

@code {
    private static readonly List<string> stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int currentStep;
    private bool isSubmitting;
    private int? submittedId;

    // Step 1
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2
    private List<WorkEntryForm.WorkEntryModel> workEntries = [new()];

    // Step 3
    private List<ReferenceForm.ReferenceModel> references = [new(), new()];

    // Step 4
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private void GoBack() => currentStep--;

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;

        var application = new JobApplication(
            new PersonalInfo(fullName, email, phone, address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        submittedId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
    }
}

.application-form {
    max-width: 700px;
    margin: 2rem auto;
    padding: 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step.active {
    border-color: #1a73e8;
    font-weight: 600;
}

.step.completed {
    border-color: #34a853;
}

.step.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    width: 100%;
    font: inherit;
    color: inherit;
    padding: 0;
}

.step.completed .step-button {
    cursor: pointer;
    color: #34a853;
}

.step-icon {
    font-size: 1.25rem;
    font-weight: bold;
}

.step-label {
    font-size: 0.8rem;
}

/* Form elements */
.step-content {
    animation: fadeIn 0.2s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateX(10px); }
    to { opacity: 1; transform: translateX(0); }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    position: relative;
}

legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #e0e0e0;
}

.btn-next, .btn-submit {
    background: #1a73e8;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #1557b0;
}

.btn-back {
    background: #f1f3f4;
    border: 1px solid #ccc;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-add {
    background: none;
    border: 1px dashed #1a73e8;
    color: #1a73e8;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    margin-bottom: 1rem;
}

.btn-remove {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: none;
    border: none;
    color: #d93025;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit {
    background: none;
    border: none;
    color: #1a73e8;
    cursor: pointer;
    font-size: 0.85rem;
    margin-left: 0.5rem;
}

/* Validation */
.validation-error {
    color: #d93025;
    background: #fce8e6;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    margin-top: 0.5rem;
}

.field-error {
    color: #d93025;
    font-size: 0.85rem;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #e0e0e0;
}

.review-section h3 {
    margin: 0 0 0.5rem;
    display: flex;
    align-items: center;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-item {
    margin-bottom: 0.75rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h2 {
    color: #34a853;
}

.application-id {
    font-size: 2rem;
    font-weight: bold;
    color: #1a73e8;
}

/* Disabled state */
button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

