.application-form {
    max-width: 700px;
    margin: 2rem auto;
    padding: 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem;
    gap: 0.25rem;
}

.step {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step.active {
    border-color: #1a73e8;
    font-weight: 600;
}

.step.completed {
    border-color: #34a853;
}

.step.future {
    opacity: 0.5;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    width: 100%;
    font: inherit;
    color: inherit;
    padding: 0;
}

.step.completed .step-button {
    cursor: pointer;
    color: #34a853;
}

.step-icon {
    font-size: 1.25rem;
    font-weight: bold;
}

.step-label {
    font-size: 0.8rem;
}

/* Form elements */
.step-content {
    animation: fadeIn 0.2s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateX(10px); }
    to { opacity: 1; transform: translateX(0); }
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    position: relative;
}

legend {
    font-weight: 600;
    padding: 0 0.5rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
