    background: #1557b0;
}

.btn-back {
    background: #f1f3f4;
    border: 1px solid #ccc;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-add {
    background: none;
    border: 1px dashed #1a73e8;
    color: #1a73e8;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    margin-bottom: 1rem;
}

.btn-remove {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: none;
    border: none;
    color: #d93025;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit {
    background: none;
    border: none;
    color: #1a73e8;
    cursor: pointer;
    font-size: 0.85rem;
    margin-left: 0.5rem;
}

/* Validation */
.validation-error {
    color: #d93025;
    background: #fce8e6;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    margin-top: 0.5rem;
}

.field-error {
    color: #d93025;
    font-size: 0.85rem;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #e0e0e0;
}

.review-section h3 {
    margin: 0 0 0.5rem;
    display: flex;
    align-items: center;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #555;
}

.review-item {
    margin-bottom: 0.75rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h2 {
    color: #34a853;
}

.application-id {
    font-size: 2rem;
    font-weight: bold;
    color: #1a73e8;
}

/* Disabled state */
button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

